// - 반사실 쌍: 민감 사실(sensitive)마다 같은 주제어를 쓰지만 특정 사람의 민감한 사정이 아닌 쌍둥이(twin)를 둔다.
//   같은 사람 표지와 같은 틀을 붙이므로 주제어나 사람 표지만으로는 둘을 가를 수 없다(7.6 의 주제어 반응, #164).
// - 같은 사람 표지·틀을 민감·정상 문장에 똑같은 횟수로 붙인다.
// - 학습 셋에는 범주어가 들어가도 된다(dev3 는 판별기만 재려고 범주어를 막았다).
//
// 칸: id, category(정상은 None), group(sensitive|twin|personal|report|general), topic(twin 의 주제 범주), frame, text, sensitive

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

let state = 20261108;
const rand = () => {
  state = (state + 0x6d2b79f5) >>> 0;
  let t = state;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const pick = (list) => list[Math.floor(rand() * list.length)];
const hasBatchim = (word) => {
  const last = [...word.normalize('NFC')].pop().codePointAt(0);
  return last >= 0xac00 && last <= 0xd7a3 && (last - 0xac00) % 28 !== 0;
};
const eun = (w) => w + (hasBatchim(w) ? '은' : '는');
const iga = (w) => w + (hasBatchim(w) ? '이' : '가');

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..', '..');
// 사람 표지 40개: 이름+직함 16, 성+호칭 8, 친족 10, 가리키는 말·관계 6.
