// 학습 틀 10개. dev3 의 틀과 다르다.
const toPlain = (s) => {
  for (const [a, b] of [['이에요.', '이다.'], ['예요.', '다.'], ['했어요.', '했다.'], ['대요.', '단다.'], ['어요.', '었다.'], ['아요.', '았다.'], ['해요.', '한다.'], ['요.', '.']]) {
    if (s.endsWith(a)) return s.slice(0, -a.length) + b;
  }
  return s;
};
const frames = [
  (p, f) => `${eun(p)} ${f}`,
  (p, f) => `${p} 얘기인데요, ${f}`,
  (p, f) => `${iga(p)} 그러는데 ${f}`,
  (p, f) => `참고로 ${eun(p)} ${f}`,
  (p, f) => `${p} 관련: ${toPlain(f)}`,
  (p, f) => `다들 알겠지만 ${eun(p)} ${f}`,
  (p, f) => `${p} 일정 때문에 말씀드리면, ${f}`,
  (p, f) => `오늘 들은 건데 ${eun(p)} ${toPlain(f)}`,
  (p, f) => `${eun(p)} 요즘 ${f}`,
  (p, f) => `(${p}) ${f}`,
];

