const add = (category, group, topic, frame, text, sensitive) => {
  if (used.has(text)) return false;
  used.add(text);
  out.push({ id: `t2-${String(out.length + 1).padStart(5, '0')}`, category, group, topic, frame, text, sensitive });
  return true;
};
// 민감 사실과 쌍둥이는 같은 사람 표지·틀로 6번씩 붙인다. 인증 정보는 사람 표지 없이 값만 바꿔 3번.
const COPIES = 6;
for (const [category, t] of Object.entries(facts)) {
  if (t.sensitive.length !== t.twin.length) throw new Error(`${category} 쌍 수가 다름`);
  const cred = category === 'Credential';
  t.sensitive.forEach((fact, i) => {
    for (let k = 0; k < (cred ? 3 : COPIES); k += 1) {
      for (let tries = 0; tries < 50; tries += 1) {
        const p = pick(people);
        const fi = Math.floor(rand() * frames.length);
        const value = pick(credValues);
        const s = cred ? fact.replace('{c}', value) : frames[fi](p, fact);
        const w = cred ? t.twin[i] : frames[fi](p, t.twin[i]);
        if (used.has(s) || (!cred && used.has(w))) continue;
        add(category, 'sensitive', '', cred ? -1 : fi, s, true);
        add('None', 'twin', category, cred ? -1 : fi, w, false);
        break;
      }
    }
  });
  for (const g of general[category]) add('None', 'general', category, -1, g, false);
}
for (const s of personal) {
  for (let k = 0; k < COPIES; k += 1) {
    const fi = Math.floor(rand() * frames.length);
    const text = frames[fi](pick(people), s);
    add('None', 'personal', '', fi, text, false);
  }
}
for (let made = 0; made < 40;) {
  const text = `${eun(pick(reportTopics))} ${pick(reportEnds)}`;
  made += add('None', 'report', '', -1, text, false) ? 1 : 0;
}

