const others = ['sentence-dev.jsonl', 'sentence-dev2.jsonl', 'sentence-dev3.jsonl', 'sentence-final.jsonl', 'shortcut-dev3.jsonl']
  .flatMap((f) => readFileSync(join(here, f), 'utf8').trim().split('\n').map((l) => {
    const j = JSON.parse(l);
    return j.text ?? `${j.a}\n${j.b}`;
  }));
const joined = others.join('\n');
for (const p of people) if (joined.includes(p)) throw new Error(`다른 셋에 나온 사람 표지: ${p}`);
const overlaps = [];
for (const t of Object.values(facts)) {
  for (const f of [...t.sensitive, ...t.twin]) {
    const core = f.replace('{c}', '').slice(0, 12);
    if (joined.includes(core)) overlaps.push(f);
  }
}
if (overlaps.length) throw new Error(`다른 셋과 앞 12글자가 겹치는 사실: ${overlaps.join(' / ')}`);
